import{_ as t,o as n,c as r,a3 as a}from"./chunks/framework.BlfGB29P.js";const i="/images/logic-studio/user-guide/typescript-de.png",g=JSON.parse('{"title":"TypeScript","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/typescript.md","filePath":"projects/logic-studio/user-guide/typescript.md","lastUpdated":1794822016000}'),l={name:"projects/logic-studio/user-guide/typescript.md"};function o(u,e,s,d,p,c){return n(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="typescript" tabindex="-1">TypeScript <a class="header-anchor" href="#typescript" aria-label="Permalink to &quot;TypeScript&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Im Bild ist absichtlich ein Typfehler eingebaut. Eine Variable vom Typ <code>number</code> erhält den Text <code>&#39;42&#39;</code>.</p><ol><li>Wähle <strong>Neues Projekt → TypeScript</strong> und gib den Code aus dem Bild ein. Die zweite Zeile gibt den Wert mit <code>ha.log(String(zahl));</code> als Text aus.</li><li>Klicke auf <strong>Testlauf starten</strong>. Das Protokoll meldet, dass ein Text keiner Zahlvariablen zugewiesen werden kann. Über <strong>Zeile 1</strong> springst du zur betroffenen Stelle.</li><li>Entferne nur die Anführungszeichen um <code>42</code>. Starte erneut. Im Protokoll erscheint <code>42</code> als Meldung.</li></ol><p><a href="/images/logic-studio/user-guide/typescript-de.png"><img src="'+i+'" alt="TypeScript mit markiertem Typfehler und Link zu Zeile 1"></a></p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="typen" tabindex="-1">Typen <a class="header-anchor" href="#typen" aria-label="Permalink to &quot;Typen&quot;">​</a></h3><p>Ein Typ beschreibt, welche Werte zulässig sind. <code>number</code> erwartet eine Zahl und <code>string</code> einen Text.</p><h3 id="typprufung" tabindex="-1">Typprüfung <a class="header-anchor" href="#typprufung" aria-label="Permalink to &quot;Typprüfung&quot;">​</a></h3><p>Sie prüft Deklarationen, Zuweisungen und Aufrufe. Korrigiere die markierte Stelle und prüfe erneut.</p><h3 id="autovervollstandigung-und-signaturen" tabindex="-1">Autovervollständigung und Signaturen <a class="header-anchor" href="#autovervollstandigung-und-signaturen" aria-label="Permalink to &quot;Autovervollständigung und Signaturen&quot;">​</a></h3><p>Nutze die Vorschläge der Skript-API. Die Signatur zeigt, welche Argumente erwartet werden.</p><h3 id="testlauf-und-runtime-fehler" tabindex="-1">Testlauf und Runtime-Fehler <a class="header-anchor" href="#testlauf-und-runtime-fehler" aria-label="Permalink to &quot;Testlauf und Runtime-Fehler&quot;">​</a></h3><p>Der Testlauf arbeitet mit simulierten Werten. Fehler beim Ausführen verweisen auf die ursprüngliche TypeScript-Zeile.</p><h3 id="globale-funktionen-und-autostart" tabindex="-1">Globale Funktionen und Autostart <a class="header-anchor" href="#globale-funktionen-und-autostart" aria-label="Permalink to &quot;Globale Funktionen und Autostart&quot;">​</a></h3><p>Wähle exportierte Funktionen aus globalen Skripten. Autostart wird pro Projekt eingestellt.</p><h3 id="play-und-protokoll" tabindex="-1">Play und Protokoll <a class="header-anchor" href="#play-und-protokoll" aria-label="Permalink to &quot;Play und Protokoll&quot;">​</a></h3><p>Speichere zuerst. Play startet die Runtime. Das Protokoll zeigt Ausgaben und Fehlermeldungen.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn du eine Zahl aus einem HA-Zustand erwartest, prüfe und konvertiere den Zustand vor der Rechnung.</p>',20)])])}const f=t(l,[["render",o]]);export{g as __pageData,f as default};
